-- Security: who did what (audit log), two-step sign-in for the admin, sessions that can be listed and ended.
CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, actor TEXT NOT NULL DEFAULT '',   -- e-mail or 'visitor'
  action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', ip TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT 'info'  -- info | warn | alert
);
CREATE INDEX audit_at ON audit_log(at);
ALTER TABLE users ADD COLUMN totp_secret TEXT;
ALTER TABLE users ADD COLUMN totp_on INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN totp_last INTEGER NOT NULL DEFAULT 0;      -- last accepted time step (a code works once)
ALTER TABLE users ADD COLUMN recovery TEXT;                             -- JSON list of SHA-256 hashes of one-time recovery codes
ALTER TABLE users ADD COLUMN last_login INTEGER;
ALTER TABLE sessions ADD COLUMN ip TEXT NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN ua TEXT NOT NULL DEFAULT '';
ALTER TABLE sessions ADD COLUMN seen_at INTEGER NOT NULL DEFAULT 0;
-- Messages from the help page, kept so the admin sees them even when the e-mail does not arrive.
CREATE TABLE messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', topic TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL, created_at INTEGER NOT NULL, read INTEGER NOT NULL DEFAULT 0, mailed INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX messages_at ON messages(created_at);
CREATE INDEX orders_status ON orders(status, created_at);
-- The seed carried sample sales figures. From here on "sold" is only what paid orders say.
UPDATE products SET sold = (SELECT count(*) FROM orders o, json_each(o.items) j
  WHERE o.status='paid' AND json_extract(j.value,'$.kind')=products.kind AND json_extract(j.value,'$.k')=products.id);
-- Prices the new pages need (the admin's own values are kept).
INSERT OR IGNORE INTO settings(k,v) VALUES('prices','{"painting":12,"postcard":2,"sticker":1,"pack":3,"calendar":8}');
-- The catalog of the new site: Farah's own stickers replace the watermarked ones, clean scans replace watermarked paintings.
UPDATE products SET deleted=1, hidden=1 WHERE kind='painting' AND id NOT LIKE 'u-%' AND id NOT IN ('hero','sparklers','dovegirl','boattop','guitar','pmoon','house','alley','blueflowers','seafish','pcartgirl','hill','pelephant','waves','deirbalah','pflower','pmoonsleep','psea','bikeride','snowglobe','boatman');
UPDATE products SET deleted=1, hidden=1 WHERE kind='postcard' AND id NOT LIKE 'u-%' AND id NOT IN ('hero','blueflowers','waves','boatman','house','dovegirl','pcartgirl','pflower','hill','boattop','psea','alley','sparklers','guitar','pmoonsleep');
UPDATE products SET deleted=1, hidden=1 WHERE kind='sticker' AND id NOT LIKE 'u-%' AND id NOT IN ('s-lemons','s-pomegranate','s-kaak','s-olives','s-jaffa','s-cactus','s-jug','s-family','s-fishers','s-coast','s-whale','girl-bike','sparklers','pmoon','dovegirl','guitar','house','boattop','seafish','waves','psea','blueflowers','pflower','pmoonsleep');
